def is_connected(important_squares, grid):
    # grid is a list of strings, 1-based indexing for rows and columns
    covered = set()
    for i in range(1, len(grid)+1):
        for j in range(1, len(grid[0])+1):
            if grid[i-1][j-1] == 'X':
                covered.add((i, j))
    if important_squares - covered:
        return False
    # BFS to check connectivity
    from collections import deque
    queue = deque(important_squares)
    visited = set(queue)
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) in covered and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
    return visited == covered

